/// <summary>
/// AVADAIOrderName
/// </summary>
/// <returns>CustName</returns>
display CustName AVADAIOrderName()
{
    CustQuotationJour AVADAICustQuotationJour;

    select OrderAccount from AVADAICustQuotationJour where AVADAICustQuotationJour.quotationId == this.QuotationId;
    return CustTable::find(AVADAICustQuotationJour.OrderAccount).name();
}

