/// <summary>
/// AVADAIisProforma
/// </summary>
/// <returns>true/false</returns>
display boolean AVADAIisProforma()
{
    CustQuotationJour AVADAICustQuotationJour;

    select QuotationId from AVADAICustQuotationJour where AVADAICustQuotationJour.quotationId == this.QuotationId;
    return AVADAICustQuotationJour.isProforma();
}

/// <summary>
/// AVADAIDeliveryStreet
/// </summary>
/// <returns>CustAccount</returns>
display LogisticsAddressStreet AVADAIDeliveryStreet()
{
    CustQuotationJour AVADAICustQuotationJour;
    LogisticsPostalAddress AVADAILogisticsPostalAddress;

    select DeliveryPostalAddress from AVADAICustQuotationJour where AVADAICustQuotationJour.quotationId == this.QuotationId
            join Street from AVADAILogisticsPostalAddress where AVADAILogisticsPostalAddress.recid      == AVADAICustQuotationJour.DeliveryPostalAddress;
    return AVADAILogisticsPostalAddress.Street;
}

